presets.css:
/* ========== 变量：改这里 ========== */
:root{
  --me-name:"Message";
  --me-status:"在线";
  --me-avatar:url("https://i.postimg.cc/fRBmc219/Screenshot-2026-10-05-02-01-38-410-com-xingin-xhs-edit.jpg");      /* 用户头像 */
  --tab1:url("https://i.postimg.cc/52vWvLZ9/retouch-2026100501265106.png");           /* 聊天 */
  --tab2:url("https://i.postimg.cc/wjJYJLSq/retouch-2026100501273563.png");           /* 朋友圈 */
  --tab3:url("https://i.postimg.cc/jdBrLZkL/retouch-2026100501280111.png");         /* 我的 */
  --dock-bg:url("");      /* 底栏图案，不想换就删掉这行和下面background里的它 */
  --c-text:#7a5548;
  --c-sub:#b7a39b;
  --c-pink:#f9dcdc;
  --c-band:#fbeeed;
  --c-page:#fdfaf8;
}

/* ========== 页面底色 ========== */
.chat-head-inbox{
  position:relative;background:var(--c-page);padding:0;
}

/* ========== 顶栏：返回键仍在左，右侧图标 ========== */
.chat-head-inbox .chat-head-bar{
  position:relative;display:flex;align-items:center;
  height:calc(44px + env(safe-area-inset-top,0px));
  padding:env(safe-area-inset-top,0px) 14px 0;
  background:transparent;border:0;box-shadow:none;
}
.chat-head-inbox .chat-back{color:var(--c-text)}
.chat-head-inbox .chat-nav-spacer{flex:1}

/* 加号：换成猫咪装饰图 */
.chat-head-inbox .chat-head-icon{
  width:42px;height:30px;margin-right:36px;padding:0;border:0;
  background:var(--plus-img) center/contain no-repeat;
  position:relative;color:var(--c-text);
}
.chat-head-inbox .chat-head-icon svg{display:none}
.chat-head-inbox .chat-head-icon::before{
  content:"+";position:absolute;left:2px;top:-4px;
  font-size:18px;font-weight:700;line-height:1;color:var(--c-text);
}

/* 装饰图标：最右侧齿轮 */
.chat-head-inbox .chat-head-bar::after{
  content:"";position:absolute;right:14px;
  top:calc(env(safe-area-inset-top,0px) + 10px);
  width:24px;height:24px;background:var(--c-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill-rule='evenodd' d='M12 5a7 7 0 1 0 0 14a7 7 0 1 0 0-14zm0 4a3 3 0 1 1 0 6a3 3 0 1 1 0-6z'/><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='3' stroke-dasharray='3.3 3.9'/></svg>") center/contain no-repeat;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill-rule='evenodd' d='M12 5a7 7 0 1 0 0 14a7 7 0 1 0 0-14zm0 4a3 3 0 1 1 0 6a3 3 0 1 1 0-6z'/><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='3' stroke-dasharray='3.3 3.9'/></svg>") center/contain no-repeat;
}

/* ========== 用户资料行：名字 / 状态 / 头像 ========== */
.chat-inbox-top{
  position:relative;display:flex;align-items:center;
  min-height:88px;padding:0 18px;background:transparent;
}
.chat-inbox-title{
  flex:1;margin:0;font-size:0;line-height:1;
}
.chat-inbox-title::before{
  content:var(--me-name);display:block;
  font-size:22px;font-weight:800;color:var(--c-text);margin-bottom:6px;
}
.chat-inbox-title::after{
  content:var(--me-status);display:block;
  font-size:13px;font-weight:400;color:var(--c-sub);
}
.chat-inbox-top::after{
  content:"";flex:none;width:54px;height:54px;border-radius:50%;
  background:var(--me-avatar) center/cover no-repeat,#e8d6d0;
}

/* 单聊 / 群聊：变成书签 / 铃铛图标，挪到右上 */
.chat-inbox-filter{
  position:absolute;z-index:3;
  top:calc(-1 * (44px + env(safe-area-inset-top,0px)) + 8px);
  right:94px;display:flex;gap:14px;background:none;padding:0;
}
.chat-inbox-filter button{
  width:26px;height:26px;padding:0;border:0;font-size:0;
  background:var(--c-text);box-shadow:none;
  opacity:.75;
}
.chat-inbox-filter button.on{opacity:1}
.chat-inbox-filter button:nth-child(1){
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.2' stroke-linejoin='round'><path d='M6 3h12v18l-6-4-6 4z'/></svg>") center/contain no-repeat;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.2' stroke-linejoin='round'><path d='M6 3h12v18l-6-4-6 4z'/></svg>") center/contain no-repeat;
}
.chat-inbox-filter button:nth-child(2){
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.2' stroke-linejoin='round' stroke-linecap='round'><path d='M6 17v-6a6 6 0 0 1 12 0v6l2 2H4z'/><path d='M10 21a2 2 0 0 0 4 0'/></svg>") center/contain no-repeat;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.2' stroke-linejoin='round' stroke-linecap='round'><path d='M6 17v-6a6 6 0 0 1 12 0v6l2 2H4z'/><path d='M10 21a2 2 0 0 0 4 0'/></svg>") center/contain no-repeat;
}

/* ========== 搜索栏装饰 ========== */
.chat-head-inbox::after{
  content:"搜索";display:block;box-sizing:border-box;
  height:34px;margin:10px 14px;padding-left:40px;
  line-height:34px;font-size:13px;color:var(--c-sub);
  border-radius:10px;background-color:var(--c-pink);
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23c9a9a0' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='6.5'/><path d='M16 16l4 4'/></svg>"),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23c9a9a0' stroke-width='2' stroke-linecap='round'><path d='M4 9V5h4M16 5h4v4M20 15v4h-4M8 19H4v-4'/></svg>");
  background-repeat:no-repeat;
  background-position:12px center,calc(100% - 12px) center;
  background-size:18px,18px;
  box-shadow:0 0 0 10px var(--c-band),-14px 0 0 10px var(--c-band),14px 0 0 10px var(--c-band);
}

/* ========== 列表：去框、去阴影、去背景 ========== */
.chat-list-sheet{
  position:relative;margin:0;padding:48px 18px 0;list-style:none;
  background:none !important;border:0 !important;
  box-shadow:none !important;border-radius:0 !important;
}
.chat-list-sheet::before{
  content:"置顶";position:absolute;left:18px;top:14px;
  font-size:18px;font-weight:800;color:var(--c-text);
}
.chat-list-sheet::after{
  content:"显示全部";position:absolute;right:18px;top:19px;
  font-size:12px;color:var(--c-sub);
}
.chat-row-wrap,
.chat-row-slider,
.chat-row{
  background:none !important;border:0 !important;box-shadow:none !important;
}
.chat-row{padding:10px 0}
.chat-ava-list{width:46px;height:46px}
.chat-row-title-text{font-size:15px;font-weight:700;color:var(--c-text)}
.chat-row-top time{font-size:11px;color:var(--c-sub)}
.chat-row-preview{font-size:13px;color:var(--c-sub)}

/* ========== 底栏：左右无间距，用原本图案 ========== */
.chat-tabdock{
  left:0 !important;right:0 !important;bottom:0 !important;
  width:100% !important;margin:0 !important;padding:0 !important;
  background:none !important;overflow:visible;
}
.chat-tabdock-pill{
  width:100%;box-sizing:border-box;margin:0;border:0;border-radius:0;
  height:calc(82px + env(safe-area-inset-bottom,0px));
  padding-bottom:env(safe-area-inset-bottom,0px);
  background:var(--dock-bg) center/cover,#f9e3df;
  box-shadow:none;overflow:visible;
  display:flex;align-items:flex-end;justify-content:space-around;
}
.chat-tabdock-pill button{
  flex:1;display:flex;flex-direction:column;align-items:center;
  background:none !important;border:0;box-shadow:none;
  padding:0 0 8px;color:var(--c-text);
}
.chat-tabdock-pill button svg,
.chat-tabdock-icon-wrap{display:none}
.chat-tabdock-pill button::before{
  content:"";display:block;width:52px;height:52px;margin-top:-26px;
  background-position:center;background-size:contain;background-repeat:no-repeat;
}
.chat-tabdock-pill button:nth-child(1)::before{background-image:var(--tab1)}
.chat-tabdock-pill button:nth-child(2)::before{background-image:var(--tab2)}
.chat-tabdock-pill button:nth-child(3)::before{background-image:var(--tab3)}
.chat-tabdock-pill button span{font-size:16px;font-weight:800;color:var(--c-text)}









/* ===== 补丁：贴在原CSS最后 ===== */
:root{
  --list-x:12px;       /* 列表左边距：头像和"置顶"都靠它 */
  --list-r:16px;       /* 列表右边距 */
  --list-bg:#fdfaf8;   /* 列表区背景：奶白；想用底栏色改成 #f9e3df */
  --dock-h:62px;       /* 底栏高度 */
  --tab-size:34px;     /* 底栏图标大小 */
  --tab-font:13px;     /* 底栏文字大小 */
}

/* 顶部上提 + 五个元素同一行 */
.chat-head-inbox{margin-top:calc(-1 * var(--top-lift));position:relative;z-index:2}
.chat-head-inbox .chat-head-bar{height:44px;padding:0 14px}
.chat-head-inbox .chat-head-bar::after{top:10px}
.chat-inbox-top{position:static}
.chat-inbox-filter{top:9px;right:90px}
.chat-inbox-filter button{width:24px;height:24px}

/* 加号：纯 + 号，不用图片 */
.chat-head-inbox .chat-head-icon{width:24px;height:24px;margin-right:38px;background:none}
.chat-head-inbox .chat-head-icon::before{content:none}
.chat-head-inbox .chat-head-icon svg{display:block;width:22px;height:22px;margin:auto}
.chat-head-inbox .chat-head-icon svg path{stroke:currentColor;fill:none;stroke-width:2.4;stroke-linecap:round}

/* 列表整体左移 */
.chat-list-sheet{padding-left:var(--list-x);padding-right:var(--list-r)}
.chat-list-sheet::before{left:var(--list-x)}
.chat-list-sheet::after{right:var(--list-r)}
.chat-row-wrap{padding:0;margin:0}
.chat-row{padding-left:0;padding-right:0}

/* 列表区背景 */
:has(> .chat-list-sheet),
.chat-list-sheet{background:var(--list-bg) !important}

/* 置顶与不置顶之间的颜文字分隔线 */
.chat-row-wrap:has([class*="pin"]) + .chat-row-wrap:not(:has([class*="pin"]))::before{
  content:"‧˚₊•┈┈┈┈ ᧔ෆ᧓ ┈┈┈┈•‧₊˚⊹";
  display:block;text-align:center;white-space:nowrap;
  padding:6px 0 2px;font-size:12px;color:#d6b9b1;
}

/* 底栏缩小 */
.chat-tabdock-pill{height:calc(var(--dock-h) + env(safe-area-inset-bottom,0px))}
.chat-tabdock-pill button{padding-bottom:6px}
.chat-tabdock-pill button::before{width:var(--tab-size);height:var(--tab-size);margin-top:0}
.chat-tabdock-pill button span{font-size:var(--tab-font)}









/* ===== 补丁3：刘海区铺色 + 群聊空页面背景 ===== */

/* 顶栏向上延伸一块奶白色，盖住刘海空白 */
.chat-head-inbox::before{
  content:"";position:absolute;left:0;right:0;bottom:100%;
  height:100vh;background:#fdfaf8;pointer-events:none;
}

/* 群聊（和单聊）列表区背景 */
.chat-scroll-list,
:has(> .chat-scroll-list){
  background:var(--list-bg,#fdfaf8) !important;
}

/* 群聊空状态的文字和图标配色 */
.chat-zero-mark{color:#c9a9a0}
.chat-zero-mark svg{stroke:currentColor}
.chat-zero-title{color:#7a5548;font-weight:700}
.chat-zero-desc{color:#b7a39b}
